if __name__ == "__main__":
    movie_titles = {item[1].casefold() for item in MOVIES}
    series_titles = {item[1].casefold() for item in SERIES}
    assert len(movie_titles) == len(MOVIES), "Duplicate movie titles found"
    assert len(series_titles) == len(SERIES), "Duplicate series titles found"
    assert len({item[0] for item in MOVIES}) == len(MOVIES), "Duplicate movie slugs found"
    assert len({item[0] for item in SERIES}) == len(SERIES), "Duplicate series slugs found"
    assert len(MOVIES) + len(SERIES) >= 500, "Catalog must contain at least 500 titles"
    print(f"Catalog valid: {len(MOVIES)} movies + {len(SERIES)} series = {len(MOVIES)+len(SERIES)} unique titles")
